// =====================================================================
// FACTORY CONFIG - ศูนย์รวมค่าตั้งค่าของโรงงานทั้งหมด
//
// วิธีแก้ค่า (เลือกอย่างใดอย่างหนึ่ง):
//   1. แก้ตัวเลข/ข้อความใน DEFAULTS ข้างล่างนี้ตรง ๆ (ง่ายสุด ใช้ได้ทุกแพลน)
//   2. หรือตั้งใน n8n Variables (Settings > Variables) ชื่อเดียวกัน - จะทับ DEFAULTS
//   3. หรือตั้ง environment variable (เฉพาะ self-hosted) - จะทับ DEFAULTS เช่นกัน
//
// แก้ที่ workflow 01 ตัวเดียวพอ: sub-workflow ทุกตัวรับ cfg ต่อจากแม่อัตโนมัติ
// =====================================================================
const DEFAULTS = {
  "OPENAI_MODEL_TEXT": "gpt-4.1",
  "GEMINI_API_BASE": "https://generativelanguage.googleapis.com",
  "GEMINI_MODEL_TEXT": "gemini-2.5-flash",
  "OPENAI_MODEL_IMAGE": "gpt-image-1",
  "OPENAI_IMAGE_QUALITY": "high",
  "IMAGE_QUALITY_COVER": "high",
  "IMAGE_QUALITY_PAGE": "medium",
  "IMAGE_QUALITY_SMALL": "low",
  "GENERATE_SEPARATE_PREVIEWS": "false",
  "PROMPT_VERSION": "v1.0.0",
  "ETSY_API_BASE": "https://openapi.etsy.com",
  "ETSY_API_KEY": "",
  "ETSY_SHOP_ID": "",
  "ETSY_LISTING_STATE": "draft",
  "ETSY_TAXONOMY_ID": 2078,
  "GDRIVE_ROOT_FOLDER_ID": "root",
  "DB_TYPE": "postgres",
  "DB_SQLITE_PATH": "/home/node/.n8n/adpf.db",
  "FACTORY_ROTATION": "planner,printable,canva,wallart,resume,spreadsheet,kids,svg",
  "ALERT_WEBHOOK_URL": "",
  "IDEA_TARGET_COUNT": 200,
  "IDEA_BATCH_SIZE": 25,
  "DUPLICATE_SIMILARITY_THRESHOLD": 0.62,
  "ALLOW_PRODUCT_REVISION": "false",
  "BUDGET_DAILY_USD": 20,
  "BUDGET_MONTHLY_USD": 300,
  "BUDGET_RUN_RESERVE_USD": 3,
  "OPENAI_IMAGE_UNIT_COST_USD": 0.19,
  "OPENAI_CHAT_RUN_COST_USD": 0.12,
  "OPENAI_PRICE_OVERRIDE_JSON": "{}",
  "LEARNING_WINDOW_DAYS": 30,
  "LEARNING_MIN_SAMPLE": 15,
  "AB_MIN_VIEWS_PER_ARM": 200,
  "AB_MIN_RELATIVE_LIFT": 0.2
};

const first = $input.first();
const incoming = first && first.json ? first.json : {};
const parentCfg = incoming.cfg && typeof incoming.cfg === 'object' ? incoming.cfg : {};

// ทั้ง $vars และ $env อาจไม่มีอยู่เลย (n8n Cloud) - แตะผ่าน try เท่านั้น
const readVars = (key) => {
  try {
    if (typeof $vars !== 'undefined' && $vars[key] !== undefined && $vars[key] !== '') {
      return $vars[key];
    }
  } catch (e) { /* Variables not available on this plan */ }
  return undefined;
};
const readEnv = (key) => {
  try {
    if (typeof $env !== 'undefined' && $env[key] !== undefined && $env[key] !== '') {
      return $env[key];
    }
  } catch (e) { /* env access blocked or not present */ }
  return undefined;
};

const cfg = {};
const sources = {};
for (const key of Object.keys(DEFAULTS)) {
  if (parentCfg[key] !== undefined) { cfg[key] = parentCfg[key]; sources[key] = 'parent'; continue; }
  const fromVars = readVars(key);
  if (fromVars !== undefined) { cfg[key] = fromVars; sources[key] = 'variables'; continue; }
  const fromEnv = readEnv(key);
  if (fromEnv !== undefined) { cfg[key] = fromEnv; sources[key] = 'env'; continue; }
  cfg[key] = DEFAULTS[key]; sources[key] = 'default';
}

return $input.all().map((item) => ({
  json: { ...item.json, cfg, cfg_sources: sources },
  binary: item.binary,
}));

// Central prompt library. Every OpenAI agent used by this workflow lives
// here so prompts are versioned with the workflow itself and can be
// diffed in git (mirrored in prompts/*.md).
const PROMPT_VERSION = $('Factory Config').first().json.cfg.PROMPT_VERSION || 'v1.0.0';
const PROMPTS = {
  "publisher_ai": {
    "id": "publisher_ai",
    "title": "Publisher AI",
    "purpose": "Build the marketplace payload and decide cross-platform compatibility.",
    "system": "You are Publisher AI. You prepare the final marketplace payload for an Etsy digital
listing and judge whether the same package can be reused on Gumroad and MiriCanvas.

Rules:
- Etsy listings created by this pipeline are ALWAYS drafts. Never set state active.
- `who_made` must be "i_did", `when_made` must be "made_to_order",
  `is_supply` must be false for finished digital products.
- Gumroad is compatible when the package contains at least one downloadable file
  and the licence permits resale outside Etsy.
- MiriCanvas is compatible only when an editable source (SVG or template spec)
  exists; a flattened PDF alone is NOT compatible.
- `approved` is false if anything in the QA report is unresolved.
- Output valid JSON only.",
    "user_template": "METADATA: {{metadata_json}}
SEO: {{seo_json}}
QA REPORT: {{qa_json}}
FILE MANIFEST: {{file_manifest}}
FACTORY PROFILE: {{factory_profile_json}}

Answer with the exact JSON contract.",
    "output_contract": "{
  "approved": true,
  "reason": "string",
  "etsy": {
    "title": "string",
    "description": "string",
    "price": 0,
    "quantity": 999,
    "tags": ["string"],
    "materials": ["string"],
    "who_made": "i_did",
    "when_made": "made_to_order",
    "is_supply": false,
    "type": "download",
    "state": "draft"
  },
  "gumroad": {"compatible": true, "reason": "string", "suggested_price_usd": 0},
  "miricanvas": {"compatible": true, "reason": "string", "editable_source": "string"}
}"
  }
};

return $input.all().map((item) => ({
  json: { ...item.json, prompt_version: PROMPT_VERSION, prompts: PROMPTS },
}));

// Unpack what 03 produced and refuse to publish anything that failed QA.
const ctx = $input.first().json;
const product = ctx.product || {};

if (product.ok !== true) {
  throw new Error(`04 Publish Engine received a product that did not pass QA: ${product.failure_reason || 'unknown'}`);
}

const files = product.files || [];
const fileByKey = Object.fromEntries(files.map((f) => [f.key, f]));

return [{
  json: {
    run_id: ctx.run_id,
    factory: ctx.factory,
    prompt_version: ctx.prompt_version,
    dry_run: ctx.dry_run === true,
    product_name: product.product_name,
    slug: product.slug,
    metadata: product.metadata,
    seo: product.seo,
    qa: product.qa,
    profile: product.profile,
    manifest: product.manifest,
    file_keys: Object.keys(fileByKey),
    listing_state: (ctx.etsy_listing_state || $('Factory Config').first().json.cfg.ETSY_LISTING_STATE || 'draft').toLowerCase(),
  },
}];

// Mustache-style renderer for the {{placeholders}} in the prompt templates.
const render = (template, vars) =>
  String(template).replace(/\{\{\s*(\w+)\s*\}\}/g, (_, key) =>
    vars[key] === undefined || vars[key] === null ? '' : String(vars[key]));

const ctx = $input.first().json;
const agent = $('Prompt Library').first().json.prompts.publisher_ai;

return [{
  json: {
    ...ctx,
    publisher_user_prompt: render(agent.user_template, {
      metadata_json: JSON.stringify(ctx.metadata, null, 2),
      seo_json: JSON.stringify(ctx.seo, null, 2),
      qa_json: JSON.stringify(ctx.qa, null, 2),
      file_manifest: JSON.stringify(ctx.manifest, null, 2),
      factory_profile_json: JSON.stringify(ctx.profile, null, 2),
    }),
  },
}];

